import {validGameJson} from './game-json.js';
const id=v=>typeof v==='string'&&v.length>0&&v.length<=160&&!/[\x00-\x1f]/.test(v);
const vector=(v,max,positive=false)=>Array.isArray(v)&&v.length===3&&v.every(x=>Number.isFinite(x)&&Math.abs(x)<=max&&(!positive||x>=.01));
export function validReplica(row){return !!row&&id(row.id)&&id(row.owner)&&Object.keys(row).every(k=>['id','owner','position','rotation','scale','visible','properties'].includes(k))&&(row.position===undefined||vector(row.position,1000000))&&(row.rotation===undefined||vector(row.rotation,360000))&&(row.scale===undefined||vector(row.scale,10000,true))&&(row.visible===undefined||typeof row.visible==='boolean')&&(row.properties===undefined||validGameJson(row.properties)&&JSON.stringify(row.properties).length<=16384);}
export function validNetworkRPC(row){return !!row&&id(row.target)&&id(row.event)&&typeof row.multicast==='boolean'&&validGameJson(row.args)&&JSON.stringify(row.args).length<=16384;}
export function interpolateReplica(object,row,delta,speed=12){const blend=speed===0?1:1-Math.exp(-Math.max(0,delta)*speed);let changed=false;for(const key of ['position','rotation','scale'])if(row[key]){if(!object[key]){object[key]=[...row[key]];changed=true;}else for(let i=0;i<3;i++){let difference=row[key][i]-object[key][i];if(key==='rotation')difference=((difference+180)%360+360)%360-180;if(difference!==0){object[key][i]+=difference*(Math.abs(difference)<1e-6?1:blend);changed=true;}}}if(row.visible!==undefined&&object.visible!==row.visible){object.visible=row.visible;changed=true;}return changed;}
